const fecha = (valor) => new Intl.DateTimeFormat('es-MX', {
  day: 'numeric',
  month: 'long',
  timeZone: 'UTC',
}).format(new Date(`${valor}T12:00:00Z`));

return $input.all().map(({ json: r }) => {
  const cantidad = Number(r.cantidad_paquetes);
  const singular = cantidad === 1;
  const mensaje = [
    `¡Hola, equipo de ${String(r.tienda).trim()}! 👋`,
    '',
    `Queremos compartirles una buena noticia: entre el ${fecha(r.semana_desde)} y el ${fecha(r.semana_hasta)}, ${cantidad} paquete${singular ? '' : 's'} ${singular ? 'pudo' : 'pudieron'} entregarse gracias a la información que nos compartieron.`,
    '',
    'La información y las indicaciones que nos hacen llegar ayudan a que el equipo de ruta encuentre soluciones y complete más entregas.',
    '',
    '¡Gracias por acompañarnos y por seguir compartiendo información útil! Cada dato hace una diferencia en la experiencia de sus clientes. 🙌',
  ].join('\n');

  return { json: { ...r, mensaje } };
});

let resumen = {};
try {
  resumen = $('Redactar mensajes').item.json;
} catch {}

const bruto = $json?.error?.message ?? $json?.error ?? 'WAHA no confirmó el envío.';
const detalle = String(bruto)
  .replace(/[\r\n]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 300) || 'WAHA no confirmó el envío.';

return [{ json: { resumen_id: resumen.resumen_id ?? '', detalle } }];
